import java.util.*;
public class Solution {
    public int longestConsecutive(final int[] A) {
        HashSet<Integer> set = new HashSet<>();
        for (int x : A) set.add(x);
        int best = 0;
        for (int x : set) {
            if (!set.contains(x - 1)) {
                int len = 1;
                while (set.contains(x + len)) len++;
                best = Math.max(best, len);
            }
        }
        return best;
    }
}

