import java.util.*;
public class Solution {
    public int solve(int[] A) {
        HashMap<Long, Integer> first = new HashMap<>();
        first.put(0L, -1);
        long sum = 0;
        int best = 0;
        for (int i = 0; i < A.length; i++) {
            sum += A[i];
            if (first.containsKey(sum)) {
                best = Math.max(best, i - first.get(sum));
            } else {
                first.put(sum, i);
            }
        }
        return best;
    }
}

import java.util.*;
public class Solution {
    public int colorful(int A) {
        List<Integer> digits = new ArrayList<>();
        if (A == 0) digits.add(0);
        while (A > 0) {
            digits.add(A % 10);
            A /= 10;
        }
        int d = digits.size();
        HashSet<Long> seen = new HashSet<>();
        for (int i = 0; i < d; i++) {
            long prod = 1;
            for (int j = i; j < d; j++) {
                prod *= digits.get(j);
                if (seen.contains(prod)) return 0;
                seen.add(prod);
            }
        }
        return 1;
    }
}

