import java.util.*;
public class Solution {
    public int solve(int[] A) {
        final int MOD = 1000000007;
        HashSet<Integer> set = new HashSet<>();
        int left = 0;
        long ans = 0;
        for (int right = 0; right < A.length; right++) {
            while (set.contains(A[right])) {
                set.remove(A[left]);
                left++;
            }
            set.add(A[right]);
            ans = (ans + (right - left + 1)) % MOD;
        }
        return (int) ans;
    }
}

import java.util.*;
public class Solution {
    public int[] solve(int[] A, int[] B) {
        HashMap<Integer, Integer> count = new HashMap<>();
        for (int x : A) count.merge(x, 1, Integer::sum);
        int[] res = new int[A.length];
        int idx = 0;
        for (int b : B) {
            int c = count.getOrDefault(b, 0);
            for (int k = 0; k < c; k++) res[idx++] = b;
            count.remove(b);
        }
        List<Integer> rest = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : count.entrySet()) {
            for (int k = 0; k < e.getValue(); k++) rest.add(e.getKey());
        }
        Collections.sort(rest);
        for (int v : rest) res[idx++] = v;
        return res;
    }
}
